CREATE FUNCTION public.foundation_require_provisioning() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF COALESCE(NEW.raw_app_meta_data->>'foundation_provisioned','false') <> 'true' THEN RAISE EXCEPTION 'Public registration disabled: server provisioning required'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.foundation_require_provisioning() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER foundation_registration_closed BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.foundation_require_provisioning();
CREATE FUNCTION public.foundation_owned_candidate() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.candidate_profiles WHERE owner_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.foundation_owned_candidate() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_owned_candidate() TO authenticated;
CREATE FUNCTION public.foundation_save_job(p_job jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF auth.uid() IS NULL OR public.foundation_owned_candidate() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; INSERT INTO public.jobs(owner_id,employer,title,original_url,canonical_url,dedup_key,fingerprint,country,location,description,housing,visa_sponsorship,international_eligible,pay_min,currency,pay_period,experience_years,languages) VALUES(auth.uid(),p_job->>'employer',p_job->>'title',p_job->>'original_url',p_job->>'canonical_url',p_job->>'dedup_key',p_job->>'fingerprint',p_job->>'country',p_job->>'location',p_job->>'description',(p_job->>'housing')::boolean,(p_job->>'visa_sponsorship')::boolean,(p_job->>'international_eligible')::boolean,(p_job->>'pay_min')::numeric,p_job->>'currency',p_job->>'pay_period',(p_job->>'experience_years')::numeric,ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_job->'languages','[]'::jsonb)))) RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.foundation_save_job(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_save_job(jsonb) TO authenticated;
CREATE FUNCTION public.foundation_save_rules(p_rules jsonb,p_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_candidate uuid; v_id uuid; v_version integer; BEGIN v_candidate:=public.foundation_owned_candidate(); IF v_candidate IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM 1 FROM public.candidate_profiles WHERE id=v_candidate FOR UPDATE; SELECT COALESCE(max(version),0)+1 INTO v_version FROM public.rule_sets WHERE candidate_id=v_candidate; INSERT INTO public.rule_sets(candidate_id,owner_id,version,rules,note) VALUES(v_candidate,auth.uid(),v_version,p_rules,p_note) RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.foundation_save_rules(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_save_rules(jsonb,text) TO authenticated;
CREATE FUNCTION public.foundation_set_rule_status(p_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_candidate uuid; BEGIN v_candidate:=public.foundation_owned_candidate(); IF v_candidate IS NULL OR p_status NOT IN ('testing','active') THEN RAISE EXCEPTION 'Unauthorized or invalid status'; END IF; PERFORM 1 FROM public.candidate_profiles WHERE id=v_candidate FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.rule_sets WHERE id=p_id AND candidate_id=v_candidate AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Rule set unavailable'; END IF; IF p_status='active' THEN UPDATE public.rule_sets SET status='archived' WHERE candidate_id=v_candidate AND status='active' AND id<>p_id; END IF; UPDATE public.rule_sets SET status=p_status WHERE id=p_id AND candidate_id=v_candidate; END $$;
REVOKE ALL ON FUNCTION public.foundation_set_rule_status(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_set_rule_status(uuid,text) TO authenticated;
CREATE FUNCTION public.foundation_record_evaluation(p_job uuid,p_rule uuid,p_classification text,p_score integer,p_reasons jsonb,p_missing jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_candidate uuid; v_id uuid; BEGIN v_candidate:=public.foundation_owned_candidate(); IF v_candidate IS NULL OR NOT EXISTS(SELECT 1 FROM public.jobs WHERE id=p_job AND owner_id=auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.rule_sets WHERE id=p_rule AND candidate_id=v_candidate AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF p_classification='compatible' AND jsonb_array_length(p_missing)>0 THEN RAISE EXCEPTION 'Missing blockers cannot be compatible'; END IF; INSERT INTO public.job_evaluations(candidate_id,owner_id,job_id,rule_set_id,classification,score,reasons,missing_data) VALUES(v_candidate,auth.uid(),p_job,p_rule,p_classification,p_score,p_reasons,p_missing) ON CONFLICT(candidate_id,job_id,rule_set_id) DO UPDATE SET classification=EXCLUDED.classification,score=EXCLUDED.score,reasons=EXCLUDED.reasons,missing_data=EXCLUDED.missing_data,evaluated_at=now() RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.foundation_record_evaluation(uuid,uuid,text,integer,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_record_evaluation(uuid,uuid,text,integer,jsonb,jsonb) TO authenticated;
CREATE FUNCTION public.foundation_select_job(p_job uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_candidate uuid; v_id uuid; BEGIN v_candidate:=public.foundation_owned_candidate(); IF v_candidate IS NULL OR NOT EXISTS(SELECT 1 FROM public.jobs WHERE id=p_job AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Unauthorized'; END IF; INSERT INTO public.applications(candidate_id,owner_id,job_id,status) VALUES(v_candidate,auth.uid(),p_job,'selected') ON CONFLICT(candidate_id,job_id) DO NOTHING RETURNING id INTO v_id; IF v_id IS NULL THEN SELECT id INTO v_id FROM public.applications WHERE candidate_id=v_candidate AND job_id=p_job; END IF; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.foundation_select_job(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_select_job(uuid) TO authenticated;
CREATE FUNCTION public.foundation_authorize_application(p_id uuid,p_confirmation boolean,p_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR p_confirmation IS DISTINCT FROM true OR length(trim(COALESCE(p_note,'')))=0 THEN RAISE EXCEPTION 'Explicit authorization required'; END IF; UPDATE public.applications SET status='authorized',authorized_at=now(),authorized_by=auth.uid(),authorization_note=p_note,updated_at=now() WHERE id=p_id AND owner_id=auth.uid() AND status IN ('selected','authorized'); IF NOT FOUND THEN RAISE EXCEPTION 'Application unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.foundation_authorize_application(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_authorize_application(uuid,boolean,text) TO authenticated;
CREATE FUNCTION public.foundation_immutable_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.owner_id<>OLD.owner_id THEN RAISE EXCEPTION 'Ownership is immutable'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.foundation_immutable_identity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER candidate_identity_immutable BEFORE UPDATE ON public.candidate_profiles FOR EACH ROW EXECUTE FUNCTION public.foundation_immutable_identity();
COMMENT ON FUNCTION public.foundation_require_provisioning() IS 'Rejects public signup even if a provider is enabled. Only trusted server app_metadata can authorize account provisioning. No admins assigned automatically.';